# Build pattern lookup from Demo 2 output - values by anti-diagonal sum
def extract_diagonal_pattern(grid):
    h, w = len(grid), len(grid[0])
    diag_to_values = {}  # i+j -> list of non-zero values
    pos_by_diag = {}     # i+j -> list of (i,j) positions

    for i in range(h):
        for j in range(w):
            s = i + j
            if s not in pos_by_diag:
                pos_by_diag[s] = []
            pos_by_diag[s].append((i,j))
            if grid[i][j] != 0:
                if s not in diag_to_values:
                    diag_to_values[s] = []
                diag_to_values[s].append(grid[i][j])

    return diag_to_values, pos_by_diag

