def solve_preserve_only(grid):
    """Only preserve known diagonals, set others to 0"""
    h, w = len(grid), len(grid[0])

    # Build map of i-j -> value from input
    diag_map = {}
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                d = i - j
                if d not in diag_map:
                    diag_map[d] = grid[i][j]
                elif diag_map[d] != grid[i][j]:
                    print(f"Conflict: ({i},{j}) has {grid[i][j]} but diag_map[d]={diag_map[d]}")

    # Apply
    result = [[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            d = i - j
            if d in diag_map:
                result[i][j] = diag_map[d]

    return result

