def build_diag_map(grid):
    """Build map from main diagonal offset (i-j) to the non-zero value on it"""
    diag_map = {}
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != 0:
                d = i - j
                if d not in diag_map:
                    diag_map[d] = grid[i][j]
                elif diag_map[d] != grid[i][j]:
                    print(f"Conflict: multiple values on diagonal {d}")
    return diag_map

def predict_by_diagonal_preservation(input_grid, output_size=None):
    """Predict output by preserving all non-zero diagonal values"""
    h, w = len(input_grid), len(input_grid[0])

    # Get max size (pad output grid)
    if output_size:
        H, W = output_size
    else:
        H, W = h, w

    # Build diagonal map from input
    diag_map = build_diag_map(input_grid)

    # Create output grid initialized to 0
    result = [[0]*W for _ in range(H)]

    # Fill in known diagonals
    for i in range(H):
        for j in range(W):
            d = i - j
            if d in diag_map:
                result[i][j] = diag_map[d]

    return result

