def predict_complete(input_grid, grid_size=(8,8)):
    """Predict full output by combining diagonal preservation + sequence formula"""
    H, W = grid_size

    # First, get known diagonal values from input
    diag_map = {}
    for i in range(len(input_grid)):
        for j in range(len(input_grid[0])):
            if input_grid[i][j] != 0:
                d = i - j
                if d not in diag_map or input_grid[i][j] == 0:
                    diag_map[d] = input_grid[i][j]

